export function recordFacilityRelocation(finance,{date,facility,currentFacility,tenure}){if(!facility||!date||!['rent','purchase'].includes(tenure)||facility.id===currentFacility?.id)return false;const purchase=tenure==='purchase'?cents(facility.purchasePrice||0):0,oldValue=currentFacility?.tenure==='purchase'?cents(finance.propertyAssetValue||currentFacility.purchasePrice||0):0;if(purchase<0||cents(finance.cash+oldValue)<purchase)return false;finance.propertyAssetValue=cents(Math.max(0,(finance.propertyAssetValue||0)-oldValue));if(oldValue){finance.cash=cents(finance.cash+oldValue);cashMove(finance,date,'Immobilienverkauf',oldValue,currentFacility.name);finance.propertyTransactions.push({date,type:'VERKAUF',facilityId:currentFacility.id,name:currentFacility.name,amount:oldValue,assetValueAfter:finance.propertyAssetValue});}if(purchase){finance.cash=cents(finance.cash-purchase);finance.propertyAssetValue=cents(finance.propertyAssetValue+purchase);cashMove(finance,date,'Immobilienkauf',-purchase,facility.name);finance.propertyTransactions.push({date,type:'KAUF',facilityId:facility.id,name:facility.name,amount:purchase,assetValueAfter:finance.propertyAssetValue});}finance.events.push({date,phase:1,kind:'IMMOBILIEN_UMZUG',text:`Standortwechsel: ${facility.name} (${tenure==='purchase'?'Kauf':'Miete'}); Szenario-Immobilienwert ${money(finance.propertyAssetValue)}.`,reference:facility.id});return true;}
