function liquidateMachine(f,date,game){const ageYears=8+Math.max(0,(new Date(`${date}T00:00:00Z`)-new Date('2027-01-01T00:00:00Z'))/86400000)/365;const marketValue=cents(Math.max(0,120000*((16-ageYears)/16)));const arrearInterest=cents((f.machineArrears||[]).reduce((sum,x)=>sum+x.interest,0)),debt=cents(f.machineLoan+arrearInterest),applied=Math.min(marketValue,debt),surplus=cents(Math.max(0,marketValue-debt)),forgiven=cents(Math.max(0,debt-marketValue));f.cash=cents(f.cash+surplus);if(surplus)cashMove(f,date,'Maschinenverwertung',surplus);f.machineLoan=0;f.machineArrears=[];f.machineSeized=true;if(game?.roomSettings)game.roomSettings.machineCount=0;f.events.push({date,phase:8,kind:'MASCHINENVERWERTUNG',text:`Maschine verwertet: Marktwert ${money(marketValue)}, davon ${money(applied)} auf Darlehen; Überschuss ${money(surplus)}, erlassene Restschuld ${money(forgiven)}.`});}
function attemptMachineInstallment(f,item,date,game){item.attempts=(item.attempts||0)+1;if(f.cash>=item.amount){f.cash=cents(f.cash-item.amount);cashMove(f,date,'Maschinenrate',-item.amount,item.id);f.machineLoan=cents(Math.max(0,f.machineLoan-item.principal));f.loanPayments=cents((f.loanPayments||0)+item.amount);f.loanPaymentsByMonth||={};f.loanInterestByMonth||={};const month=date.slice(0,7);f.loanPaymentsByMonth[month]=cents((f.loanPaymentsByMonth[month]||0)+item.amount);f.loanInterestByMonth[month]=cents((f.loanInterestByMonth[month]||0)+item.interest);f.loanInstallmentsPaid=(f.loanInstallmentsPaid||0)+1;f.machineArrears=f.machineArrears.filter(x=>x.id!==item.id);f.events.push({date,phase:8,kind:'MASCHINENRATE',text:`Maschinenrate ${money(item.amount)} bezahlt (${money(item.interest)} Zins); Restschuld ${money(f.machineLoan)}.`});return true;}item.nextRetryDate=nextWorkday(addCalendarDays(date,7));f.events.push({date,phase:8,kind:'MASCHINENRATE_FEHLGESCHLAGEN',text:`Maschinenrate ${money(item.amount)} mangels Liquidität nicht bezahlt; nächster Vollzahlungsversuch ${item.nextRetryDate}.`});if(f.machineArrears.length>=3)liquidateMachine(f,date,game);return false;}
export function processMachineLoanDue(f,date,game=null){if(f.machineSeized||f.machineLoan<=0)return false;let followingDate=date;do{followingDate=addCalendarDays(followingDate,1);}while(!isWorkday(followingDate));const month=date.slice(0,7),lastWorkday=isWorkday(date)&&followingDate.slice(0,7)!==month,due=date==='2027-01-29'||(date>'2027-01-29'&&lastWorkday);let processed=false;if(due&&f.lastLoanPaymentMonth!==month){const seq=(f.loanInstallmentsDue||0)+1,interest=cents(f.machineLoan*.05/12),amount=seq===84?cents(f.machineLoan+interest):339.21,item={id:`ML-${seq}`,installment:seq,dueDate:date,amount,interest,principal:cents(amount-interest),attempts:0,nextRetryDate:nextWorkday(addCalendarDays(date,7))};f.loanInstallmentsDue=seq;f.lastLoanPaymentMonth=month;f.machineArrears||=[];f.machineArrears.push(item);attemptMachineInstallment(f,item,date,game);processed=true;}if(!f.machineSeized){for(const item of [...(f.machineArrears||[])].filter(x=>x.nextRetryDate<=date)){if(item.dueDate===date)continue;attemptMachineInstallment(f,item,date,game);processed=true;if(f.machineSeized)break;}}return processed;}
export function drawForMachineLoan(f,date,game=null){const item=(f.machineArrears||[]).find(x=>true);if(!item)return false;const draw=cents(Math.max(0,item.amount-f.cash)),free=cents(f.overdraftLimit-f.overdraftDrawn);if(draw<=0||draw>free)return false;f.overdraftDrawn=cents(f.overdraftDrawn+draw);f.cash=cents(f.cash+draw);cashMove(f,date,'Dispoziehung',draw,item.id);f.events.push({date,phase:8,kind:'DISPO_MASCHINENRATE',text:`Exakt ${money(draw)} Dispo für die fällige Maschinenrate gezogen.`});return attemptMachineInstallment(f,item,date,game);}
function fkqSpread(q){const phi=(1+Math.sqrt(5))/2,k=Math.log(phi)/25;if(q<15)return .005;if(q<=90)return .005+5*(1-Math.exp(-k*(q-15)))/(1-Math.exp(-75*k))/100;return .055+2.5*(Math.exp(k*(q-90))-1)/(Math.exp(10*k)-1)/100;}
function refreshCompanyInterest(f,game,assets,date){const debt=Math.max(0,(f.openingPayables||0)+(f.machineLoan||0)+(f.overdraftDrawn||0)+(f.unpaidCosts||0));const q=assets>0?Math.min(100,debt/assets*100):100;const mro=Number(game.macro.policyRate??.035);f.companyInterestRate=mro+fkqSpread(q);f.overdraftRate=f.companyInterestRate*1.08;f.events.push({date,phase:1,kind:'DISPOZINSATZ',text:`Jahreszins aktualisiert: Unternehmenszins ${((f.companyInterestRate)*100).toFixed(2)} %, Dispozins 8 % darüber (${(f.overdraftRate*100).toFixed(2)} %).`});}
export function refreshOverdraftLimit(f,game,date){const isQuarterStart=['-01-01','-04-01','-07-01','-10-01'].some(s=>date.endsWith(s));if(!isQuarterStart)return;const assets=Math.max(0,f.cash+getOpenReceivables(f)+f.openingInventoryValue+(f.propertyAssetValue||0));f.overdraftLimit=cents(assets*.1);if(date.endsWith('-01-01')||f.overdraftRate==null)refreshCompanyInterest(f,game,assets,date);f.events.push({date,phase:1,kind:'DISPOLIMIT',text:`Quartalslimit aktualisiert: ${money(f.overdraftLimit)} (10 % aus vereinfachter Bilanzsumme ${money(assets)}).`});}
export function processTaxPayment(f,date){recalculateTaxPeriods(f);for(const period of f.taxPeriods){if(period.paidAt||period.settledAt)continue;if(!period.dueDate){let y=Number(period.month.slice(0,4)),m=Number(period.month.slice(5,7))+1;if(m===13){m=1;y++;}let due=`${y}-${String(m).padStart(2,'0')}-10`;while(!isWorkday(due))due=addCalendarDays(due,1);period.dueDate=due;}if(period.dueDate>date||(period.nextRetryDate&&period.nextRetryDate>date))continue;if(period.amount<=0){period.settledAt=date;f.events.push({date,phase:8,kind:'SIMTAX_GUTHABEN',text:`SimTAX-Periode ${period.month}: kein Zahlbetrag; Guthaben ${money(period.creditCarriedForward)} wird vorgetragen.`});continue;}if(f.cash>=period.amount){f.cash=cents(f.cash-period.amount);period.paidAt=date;period.status='BEZAHLT';cashMove(f,date,'SimTAX',-period.amount,period.month);f.events.push({date,phase:8,kind:'SIMTAX_ZAHLUNG',text:`SimTAX-Vorauszahlung ${period.month}: Ausgang ${money(period.outputTax)}, Vorsteuer ${money(period.inputTax)}, Guthaben ${money(period.creditBroughtForward)}, netto ${money(period.amount)} gezahlt.`});}else{if(!period.firstFailedAt){period.firstFailedAt=date;period.retryFailures=0;const reminderDate=shiftWeekend(addCalendarDays(date,10));period.reminderDate=reminderDate;period.formalNoticeDate=shiftWeekend(addCalendarDays(reminderDate,14));period.nextRetryDate=nextWorkday(addCalendarDays(date,7));}else{period.retryFailures=(period.retryFailures||0)+1;if(period.retryFailures>=8){period.status='NIEDERLAGE';period.lossAt=date;f.gameLost=true;f.lossReason=`SimTAX ${period.month}: acht wöchentliche Retry-Fehlschläge`;f.events.push({date,phase:8,kind:'ZAHLUNGSAUSFALL_SPIELVERLOREN',text:`SimTAX ${period.month}: achter wöchentlicher Retry-Fehlschlag; Spiel verloren.`});}else period.nextRetryDate=nextWorkday(addCalendarDays(date,7));}period.status='OFFEN';period.failedAt=date;f.events.push({date,phase:8,kind:'SIMTAX_FEHLER',text:`SimTAX-Periode ${period.month}: netto ${money(period.amount)} mangels Liquidität offen (${period.retryFailures||0}/8 Retry-Fehlschläge).`});}}
 for(const period of f.taxPeriods){if(period.paidAt||period.settledAt||!period.firstFailedAt)continue;if(!period.reminderAt&&period.reminderDate<=date){period.reminderAt=date;f.events.push({date,phase:8,kind:'ZAHLUNGSERINNERUNG',text:`SimTAX-Periode ${period.month}: Zahlungserinnerung.`,reference:`TAX-${period.month}`});}if(!period.formalNoticeAt&&period.formalNoticeDate<=date){period.formalNoticeAt=date;f.events.push({date,phase:8,kind:'FORMELLE_MAHNUNG',text:`SimTAX-Periode ${period.month}: formelle Mahnung.`,reference:`TAX-${period.month}`});}}
}
export function processFinancialDay(f,date,game=null){const paidOrders=settleCustomerPayments(f,date,game);processMachineLoanDue(f,date,game);processOutstandingCosts(f,date,game);processTaxPayment(f,date);accrueOverdraftInterest(f);return paidOrders;}

export function recordMaterialPurchase(finance,materials,date,supplierId=null,game=null){const prices=game?materialPrices(game):MATERIAL_PRICE_BASELINE,supplier=game?.network?.suppliers?.find(x=>x.id===supplierId),reliabilityPremium=supplier?Math.max(0,(90-supplier.reliability)*.002):0;const cost=cents(Object.entries(materials||{}).reduce((sum,[m,q])=>sum+q*(prices[m]||0),0)*(1+reliabilityPremium));finance.materialPurchases=cents((finance.materialPurchases||0)+cost);const paid=payExpense(finance,date,'MATERIAL',supplier?.name||'Szenario-Lieferant Material',cost,supplierId?{supplierId}:{});let inputTax=0;if(supplier){inputTax=roundSimTaxForPosition(cost);addTaxComponent(finance,date.slice(0,7),'inputTax',inputTax);finance.events.push({date,phase:2,kind:'SIMTAX_VORSTEUER',text:`Qualifizierter Lieferantenbeleg ${supplier.name}: Vorsteuer-SimTAX ${money(inputTax)} auf ${money(cost)} netto.`,reference:`EINGANG-${date}-${supplierId}`});}if(supplier&&paid){supplier.paymentMoral=Math.min(100,supplier.paymentMoral+1);supplier.relationship=Math.min(100,supplier.relationship+1);supplier.lastPaidAt=date;supplier.lastLateDays=0;}finance.events.push({date,phase:2,kind:'MATERIALKAUF',text:`Materialzugang von ${supplier?.name||'Szenario-Lieferant'} zum aktuellen V1-Preisszenario: ${money(cost)} netto${inputTax?`, Vorsteuer-SimTAX ${money(inputTax)}`:''}.`});return cost;}
